/**
 * Drift gate: crates/cascivo-html/assets/** and src/*_gen.rs are generated by
 * scripts/html-kit (part of `pnpm regen`). Regenerate into a temp dir and require equality
 * with the committed files, so a CSS/manifest change cannot land without its generated output.
 */
import assert from 'node:assert/strict'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'
import { generateAll } from '../html-kit/gen-rust.ts'

const crate = fileURLToPath(new URL('../../crates/cascivo-html/', import.meta.url))

function walk(dir: string, base = dir): string[] {
  return readdirSync(dir).flatMap((f) => {
    const p = join(dir, f)
    return statSync(p).isDirectory() ? walk(p, base) : [p.slice(base.length + 1)]
  })
}

test('committed cascivo-html generated files match a fresh generation', async () => {
  const fresh = await generateAll()
  for (const [rel, content] of fresh)
    assert.equal(
      readFileSync(join(crate, rel), 'utf8'),
      content,
      `${rel} is stale — run \`pnpm html-kit:generate\` and commit`,
    )
  // Hand-written extras (assets/extra/**) are not generated; every other asset must be.
  const generatedDirs = ['assets/css/', 'assets/themes/']
  const committed = walk(crate).filter((f) => generatedDirs.some((d) => f.startsWith(d)))
  for (const f of committed) assert.ok(fresh.has(f), `${f} is committed but no longer generated`)
})
